import{_ as r,o as t,c as a,ae as e}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"产品发布 - 2026-06-08","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-06-08-product.md","filePath":"daily/2026-06-08-product.md"}'),n={name:"daily/2026-06-08-product.md"};function i(s,o,g,p,l,h){return t(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="产品发布-2026-06-08" tabindex="-1">产品发布 - 2026-06-08 <a class="header-anchor" href="#产品发布-2026-06-08" aria-label="Permalink to &quot;产品发布 - 2026-06-08&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日AI产品领域动态聚焦于功能更新和工作流程优化。Notion AI新增日历集成和图像生成能力提升，Figma推出AI设计代理，而digital.ai简化开发者应用上线流程。最值得关注的是微软Copilot，其基于聊天的AI交互工具，为组织和个人提供强大支持。</p><hr><h3 id="_1-notion-ai功能更新与新特性" tabindex="-1">1. Notion AI功能更新与新特性 <a class="header-anchor" href="#_1-notion-ai功能更新与新特性" aria-label="Permalink to &quot;1. Notion AI功能更新与新特性&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://matthiasfrank.de/en/notion-updates" target="_blank" rel="noreferrer">Notion Updates &amp; New Features - Matthias Frank</a></p><p><strong>一句话摘要</strong>: Notion AI新增日历集成、图像生成限制提升和数据库自动化</p><p><strong>能解决什么问题</strong>: 提高工作效率，简化日程协调和数据管理</p><p><strong>产品应用</strong>: 适用于需要日程管理、视觉设计和数据库自动化的团队</p><p><strong>示例场景</strong>: 自动安排会议并生成会议邀请</p><hr><h3 id="_2-工作流概览-·-digital-ai-发布" tabindex="-1">2. 工作流概览 · digital.ai 发布 <a class="header-anchor" href="#_2-工作流概览-·-digital-ai-发布" aria-label="Permalink to &quot;2. 工作流概览 · digital.ai 发布&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: digital.ai 发布23.3引入自助工作流简化开发者应用上线。</p><p><strong>能解决什么问题</strong>: 降低应用上线复杂性，确保云安全和合规性。</p><p><strong>产品应用</strong>: 适用于需要自动化部署和优化云应用的场景。</p><p><strong>示例场景</strong>: 开发者使用工作流自动化CI/CD流程。</p><hr><h3 id="_3-产品副驾驶——软件产品团队的ai助手" tabindex="-1">3. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_3-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;3. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: Product Copilot是集成在Jira和Confluence中的AI助手，帮助产品团队优化工作流程。</p><p><strong>能解决什么问题</strong>: 解决产品团队在任务管理、协作和文档更新中的效率问题。</p><p><strong>产品应用</strong>: 适用于需要提高产品管理效率和团队协作的软件产品团队。</p><p><strong>示例场景</strong>: 产品负责人使用Product Copilot创建清晰任务票和维护文档。</p><hr><h3 id="_4-figma产品新闻和发布说明" tabindex="-1">4. Figma产品新闻和发布说明 <a class="header-anchor" href="#_4-figma产品新闻和发布说明" aria-label="Permalink to &quot;4. Figma产品新闻和发布说明&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/release-notes" target="_blank" rel="noreferrer">Figma product news and release notes</a></p><p><strong>一句话摘要</strong>: Figma推出AI设计代理和Make功能更新。</p><p><strong>能解决什么问题</strong>: 提高设计效率，自动化常规工作，尊重设计系统。</p><p><strong>产品应用</strong>: 适用于专业、组织和企业计划的完整座位用户。</p><p><strong>示例场景</strong>: 设计师使用AI代理生成和混合设计。</p><hr><h3 id="_5-微软copilot-面向组织的ai工具" tabindex="-1">5. 微软Copilot | 面向组织的AI工具 <a class="header-anchor" href="#_5-微软copilot-面向组织的ai工具" aria-label="Permalink to &quot;5. 微软Copilot | 面向组织的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软Copilot提供基于聊天的生成式AI交互，助力组织和个人。</p><p><strong>能解决什么问题</strong>: 提高工作效率，增强安全性，促进协作和创新。</p><p><strong>产品应用</strong>: 可应用于企业日常运营，如写作、编程、安全防护和数据分析。</p><p><strong>示例场景</strong>: 企业员工使用Microsoft 365 Copilot提高文档处理效率。</p><hr><h3 id="_6-什么是ai副驾驶-salesforce" tabindex="-1">6. 什么是AI副驾驶 | Salesforce <a class="header-anchor" href="#_6-什么是ai副驾驶-salesforce" aria-label="Permalink to &quot;6. 什么是AI副驾驶 | Salesforce&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.salesforce.com/agentforce/ai-copilot" target="_blank" rel="noreferrer">What is an AI Copilot | Salesforce</a></p><p><strong>一句话摘要</strong>: AI副驾驶通过自动化和智能辅助提升工作效率。</p><p><strong>能解决什么问题</strong>: 解决重复性任务多、决策复杂、信息处理量大的问题。</p><p><strong>产品应用</strong>: 可应用于各行业，如Salesforce的Agentforce，提升客户服务效率。</p><p><strong>示例场景</strong>: 在房地产营销中，AI副驾驶自动生成营销内容。</p><hr><h3 id="_7-figma-维基百科" tabindex="-1">7. Figma - 维基百科 <a class="header-anchor" href="#_7-figma-维基百科" aria-label="Permalink to &quot;7. Figma - 维基百科&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Figma" target="_blank" rel="noreferrer">Figma - Wikipedia</a></p><p><strong>一句话摘要</strong>: Figma推出新功能，加强设计师与开发者协作。</p><p><strong>能解决什么问题</strong>: 解决设计和开发流程中的协作难题。</p><p><strong>产品应用</strong>: 适用于产品设计，通过集成工具提高团队效率。</p><p><strong>示例场景</strong>: 设计师和开发者共同在Figma上协作完成UI设计。</p><hr><h3 id="_8-2026年notion-ai是否值得投资-firebear-studio" tabindex="-1">8. 2026年Notion AI是否值得投资 - Firebear Studio <a class="header-anchor" href="#_8-2026年notion-ai是否值得投资-firebear-studio" aria-label="Permalink to &quot;8. 2026年Notion AI是否值得投资 - Firebear Studio&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://firebearstudio.com/blog/what-is-notion.html" target="_blank" rel="noreferrer">Whether Notion AI Is Worth It in 2026 - Firebear Studio</a></p><p><strong>一句话摘要</strong>: Notion AI通过人工智能提升内容创造和管理效率。</p><p><strong>能解决什么问题</strong>: 解决团队协作和内容管理效率低下的问题。</p><p><strong>产品应用</strong>: 适用于需要高效协作和内容管理的产品，如企业知识库、项目管理等。</p><p><strong>示例场景</strong>: 企业使用Notion AI管理项目进度和文档。</p><hr><h3 id="_9-在figma设计中使用ai工具" tabindex="-1">9. 在Figma设计中使用AI工具 <a class="header-anchor" href="#_9-在figma设计中使用ai工具" aria-label="Permalink to &quot;9. 在Figma设计中使用AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://help.figma.com/hc/en-us/articles/23870272542231-Use-AI-tools-in-Figma-Design" target="_blank" rel="noreferrer">Use AI tools in Figma Design</a></p><p><strong>一句话摘要</strong>: 探索Figma设计中所有可用的AI功能。</p><p><strong>能解决什么问题</strong>: 提高设计效率，快速找到所需资源并保持工作流程。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI功能加速设计流程和资源查找。</p><p><strong>示例场景</strong>: 设计师使用Figma AI工具快速迭代设计草图。</p><hr><h3 id="_10-figma-ai工具向所有用户推出的发布日期" tabindex="-1">10. Figma AI工具向所有用户推出的发布日期 <a class="header-anchor" href="#_10-figma-ai工具向所有用户推出的发布日期" aria-label="Permalink to &quot;10. Figma AI工具向所有用户推出的发布日期&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://forum.figma.com/ask-the-community-7/release-date-for-ai-tool-rollout-to-all-users-26131" target="_blank" rel="noreferrer">Release Date for AI Tool Rollout to All Users? | Figma Forum</a></p><p><strong>一句话摘要</strong>: Figma AI工具目前处于有限测试阶段，正在逐步推出。</p><p><strong>能解决什么问题</strong>: 解决设计师在UI/UX设计中自动化和效率问题。</p><p><strong>产品应用</strong>: 适用于产品设计，通过AI功能提升设计工作流程。</p><p><strong>示例场景</strong>: 设计师使用Figma AI自动生成布局和元素。</p><hr>',75)])])}const f=r(n,[["render",i]]);export{c as __pageData,f as default};
